public class RotatorCheckerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Object verdict(Rotator impl) {
        try {
            return RotatorChecker.isCorrect(impl);
        } catch (Throwable crash) {
            return "isCorrect threw " + crash.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        check("accepts the correct implementation", true, verdict(new CorrectRotator()));
        check("accepts an equally correct implementation", true, verdict(new AlsoCorrectRotator()));
        check("rejects the rotation that goes the wrong way", false, verdict(new LeftRotator()));
        check("rejects the crash on an empty array", false, verdict(new EmptyCrashRotator()));
        check("rejects the crash when k is larger than the array", false, verdict(new BigShiftRotator()));
        check("rejects the version that modifies the caller's array", false, verdict(new InPlaceRotator()));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

class CorrectRotator implements Rotator {
    public int[] rotateRight(int[] values, int k) {
        int n = values.length;
        if (n == 0) return new int[0];
        int[] out = new int[n];
        for (int i = 0; i < n; i++) {
            out[(i + k) % n] = values[i];
        }
        return out;
    }
}

class AlsoCorrectRotator implements Rotator {
    public int[] rotateRight(int[] values, int k) {
        int n = values.length;
        if (n == 0) return new int[0];
        int shift = k % n;
        int[] out = new int[n];
        System.arraycopy(values, n - shift, out, 0, shift);
        System.arraycopy(values, 0, out, shift, n - shift);
        return out;
    }
}

class LeftRotator implements Rotator {
    public int[] rotateRight(int[] values, int k) {
        int n = values.length;
        if (n == 0) return new int[0];
        int[] out = new int[n];
        for (int i = 0; i < n; i++) {
            out[i] = values[(i + k) % n];
        }
        return out;
    }
}

class EmptyCrashRotator implements Rotator {
    public int[] rotateRight(int[] values, int k) {
        int n = values.length;
        int shift = k % n;
        int[] out = new int[n];
        for (int i = 0; i < n; i++) {
            out[(i + shift) % n] = values[i];
        }
        return out;
    }
}

class BigShiftRotator implements Rotator {
    public int[] rotateRight(int[] values, int k) {
        int n = values.length;
        if (n == 0) return new int[0];
        int[] out = new int[n];
        for (int i = 0; i < n; i++) {
            out[i + k] = values[i];
        }
        return out;
    }
}

class InPlaceRotator implements Rotator {
    public int[] rotateRight(int[] values, int k) {
        int n = values.length;
        if (n == 0) return values;
        for (int turn = 0; turn < k % n; turn++) {
            int last = values[n - 1];
            for (int i = n - 1; i > 0; i--) values[i] = values[i - 1];
            values[0] = last;
        }
        return values;
    }
}

