/**
 * TASK: Write the checks that decide whether a Rotator is correct.
 *
 *   rotateRight(values, k) returns a NEW array with the elements moved k
 *   places to the right; the element that falls off the end wraps round.
 *   k is never negative but may be larger than the array. The array passed in
 *   must not be modified. An empty array rotates to an empty array.
 *   Examples: rotateRight({1,2,3,4,5}, 2) -> {4,5,1,2,3}
 *             rotateRight({1,2,3}, 5)     -> {2,3,1}
 *             rotateRight({}, 3)          -> {}
 *
 * isCorrect(impl) must return true for an implementation that honours the
 * contract and false for one that does not. Some broken implementations THROW
 * instead of returning a value, so a crash counts as a failure: wrap your calls
 * in try/catch and return false if anything is thrown.
 *
 * One happy-path call is not a test suite. Choose inputs that expose specific
 * bugs, including the boundary cases named in the contract.
 */
interface Rotator {
    /* Provided -- do not edit. */
    int[] rotateRight(int[] values, int k);
}

public class RotatorChecker {

    public static boolean isCorrect(Rotator impl) {
        try {
            if (!same(impl.rotateRight(new int[] {1, 2, 3, 4, 5}, 2), new int[] {4, 5, 1, 2, 3})) return false;
            if (!same(impl.rotateRight(new int[] {1, 2, 3}, 5), new int[] {2, 3, 1})) return false;
            if (!same(impl.rotateRight(new int[] {1, 2, 3}, 0), new int[] {1, 2, 3})) return false;
            if (!same(impl.rotateRight(new int[] {}, 3), new int[] {})) return false;
            if (!same(impl.rotateRight(new int[] {7}, 4), new int[] {7})) return false;

            int[] original = {1, 2, 3, 4};
            impl.rotateRight(original, 1);
            if (!same(original, new int[] {1, 2, 3, 4})) return false;
        } catch (Throwable crash) {
            return false;
        }
        return true;
    }

    private static boolean same(int[] actual, int[] expected) {
        return java.util.Arrays.equals(actual, expected);
    }
}
